-- Import the 64 official Pusti Happy Time products and price list.
-- DP carton rate = lower first rate; retailer carton rate = higher second rate.
-- per-piece rates are generated by the database from carton rate / pieces per carton.
-- Re-running this script updates these SKU codes instead of creating duplicates.

INSERT INTO public.skus
  (sku_code, category, product_name, product_size, pieces_per_carton,
   carton_rate, retailer_carton_rate, mrp, item_weight_kg, active)
SELECT
  v.sku_code,
  v.category,
  v.product_name,
  COALESCE(
    substring(v.product_name from '[0-9]+[.]?[0-9]*[[:space:]]*[[:alpha:]]{2}'),
    substring(v.product_name from '[(][^)]*[)]'),
    v.product_name
  ) AS product_size,
  v.pieces_per_carton,
  v.dp_carton_rate,
  v.retailer_carton_rate,
  v.mrp,
  v.item_weight_kg,
  true
